const responses = $input.all();
const sources = $('Official Source Registry').all().map((item) => item.json);
const out = [];
const seen = new Set();
const allowed = /penalt|enforce|disciplin|sanction|contravention|anti[- ]?money|money[- ]?launder|administrative|prosecution|罚款|处罚|反洗钱|行政处罚|监管措施|纪律处分|执法/i;

const cleanText = (value) => String(value || '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;|&#160;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();

for (let index = 0; index < responses.length; index += 1) {
  const source = sources[index];
  if (!source) continue;

  const response = responses[index].json;
  const raw = typeof response === 'string'
    ? response
    : String(response?.data ?? response?.body ?? JSON.stringify(response));

  const push = (urlValue, titleValue, dateValue = null) => {
    let parsed;
    try {
      parsed = new URL(String(urlValue || ''), source.url);
    } catch {
      return;
    }

    if (parsed.protocol !== 'https:') return;
    const host = parsed.hostname.toLowerCase();
    if (!source.allowedDomains.some((domain) => host === domain || host === `www.${domain}` || host.endsWith(`.${domain}`))) return;

    parsed.hash = '';
    const url = parsed.href;
    const title = cleanText(titleValue);
    if (!title || !allowed.test(`${title} ${url}`) || seen.has(url)) return;

    seen.add(url);
    out.push({
      json: {
        ...source,
        source_page: source.url,
        url,
        title,
        publication_date: dateValue || null,
        discovered_at: new Date().toISOString(),
        pipeline_version: 'regintel-n8n-v1',
      },
    });
  };

  if (source.mode === 'json') {
    try {
      const payload = typeof response === 'object' && response?.result ? response : JSON.parse(raw);
      const records = payload?.result?.records || payload?.data || payload?.records || [];
      for (const record of records) {
        push(
          record.url || record.link || record.hyperlink,
          record.title_en || record.title || record.name,
          record.press_release_date || record.publish_date || record.date,
        );
      }
    } catch (error) {
      throw new Error(`Official JSON adapter failed for ${source.source_code}: ${error.message}`);
    }
    continue;
  }

  for (const match of raw.matchAll(/<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)) {
    const nearby = raw.slice(match.index || 0, (match.index || 0) + match[0].length + 160);
    const isoDate = nearby.match(/\b(20\d{2}-\d{2}-\d{2})\b/)?.[1] || null;
    const englishDate = nearby.match(/\b(\d{1,2}\s+[A-Za-z]+\s+20\d{2})\b/)?.[1] || null;
    push(match[1].replace(/&amp;/g, '&'), match[2], isoDate || englishDate);
  }
}

return out.slice(0, 180);

const candidates = $('Discover Official Candidates').all();
const responses = $input.all();

return responses.map((item, index) => {
  const candidate = candidates[index]?.json;
  if (!candidate) throw new Error(`Missing candidate pairing at item ${index}`);

  const response = item.json;
  const raw = typeof response === 'string' ? response : String(response?.data ?? response?.body ?? '');
  const officialText = raw
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;|&#160;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 50000);
  const query = `${candidate.regulator} ${candidate.title} ${candidate.jurisdiction === 'CN' ? '行政处罚 监管 执法' : 'enforcement disciplinary penalty'}`.slice(0, 500);

  return {
    json: {
      ...candidate,
      official_text: officialText,
      anysearch_query: query,
      document_type: 'official_announcement',
      verification_status: 'unverified',
    },
  };
});

const candidates = $('Build Verification Package').all();
const searchItems = $input.all();

return searchItems.map((item, index) => {
  const candidate = candidates[index]?.json;
  if (!candidate) throw new Error(`Missing verification package pairing at item ${index}`);

  const search = item.json || {};
  const results = search.results || search.data || search.items || [];
  const evidence = (Array.isArray(results) ? results : []).slice(0, 5).map((result) => ({
    title: result.title || result.name || '',
    url: result.url || result.link || '',
    snippet: result.snippet || result.description || result.content || '',
    source: result.source || '',
  }));
  const decision = {
    decision_number: null,
    decision_date: null,
    publication_date: null,
    case_type: 'fine|warning|improvement_order|suspension|revocation|prohibition|prosecution|other',
    severity: 'low|medium|high|critical',
    subjects: [{ original_name: '', canonical_name: '', entity_type: 'organization|person', sector: '', subject_role: 'respondent', evidence_span: '' }],
    violations: [{ verbatim_wording: '', normalized_category: 'AML_CFT|KYC_CDD|EDD|BENEFICIAL_OWNERSHIP|SANCTIONS_SCREENING|TRANSACTION_MONITORING|STR_SAR|RECORDKEEPING|GOVERNANCE|MARKET_CONDUCT|FX|PAYMENTS|OTHER', legal_citation: '', source_span: '', classification_basis: 'confirmed_by_regulator|analyst_inference', confidence: 0 }],
    penalties: [{ subject_name: '', penalty_type: '', currency: null, amount: null, original_amount_text: '', applies_to: 'institution|person|mixed|unknown', combined_amount: false, amount_allocation_status: 'not_applicable|explicit|unallocated_composite|needs_review', evidence_span: '' }],
    control_findings: [{ control_domain: '', observed_failure: '', possible_root_cause: '', classification: 'confirmed_by_regulator|analyst_inference', evidence_span: '', confidence: 0 }],
    summary_en: '',
    summary_cn: '',
    confidence: 0,
  };
  const schema = {
    relevance: 'enforcement|not_enforcement|uncertain',
    announcement_type: 'enforcement|guidance|policy|consultation|unrelated',
    decisions: [decision],
    confidence: 0,
    missing_fields: [],
    review_notes: '',
  };
  const instructions = `You are a regulatory enforcement intelligence analyst. Return JSON only. Treat the official regulator text as primary evidence. Search results are corroboration only and may be wrong. Do not invent facts, dates, legal citations, entities, amounts, currencies, or control failures. Preserve exact original-currency amounts. Split multiple decisions into separate decisions and distinguish institutions from named people. Preserve verbatim violation and evidence spans. Never assign an entire composite fine to AML unless the regulator explicitly apportions it. Mark inferred control findings as analyst_inference. Do not set verified or published status. If the text is not a formal regulator/court/enforcement action, classify it not_enforcement and return an empty decisions array. Use null for missing values. Required JSON shape: ${JSON.stringify(schema)}`;
  const content = {
    source_code: candidate.source_code,
    jurisdiction: candidate.jurisdiction,
    regulator: candidate.regulator,
    official_url: candidate.url,
    title: candidate.title,
    publication_date: candidate.publication_date,
    official_text: candidate.official_text,
    corroboration: evidence,
  };

  return {
    json: {
      ...candidate,
      anysearch_evidence: evidence,
      ai_request: {
        model: 'deepseek-chat',
        temperature: 0,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: instructions },
          { role: 'user', content: JSON.stringify(content) },
        ],
      },
    },
  };
});

const bases = $('Build Strict AI Analysis').all();
const responses = $input.all();

return responses.map((item, index) => {
  const base = bases[index]?.json;
  if (!base) throw new Error(`Missing AI request pairing at item ${index}`);

  const response = item.json || {};
  let analysis = {};
  try {
    const text = response?.choices?.[0]?.message?.content ?? response?.output_text ?? '';
    analysis = typeof text === 'object'
      ? text
      : JSON.parse(String(text).replace(/^```json\s*|```$/g, '').trim());
  } catch (error) {
    analysis = {
      relevance: 'uncertain',
      confidence: 0,
      missing_fields: ['ai_analysis'],
      review_notes: `AI analysis unavailable or invalid JSON: ${error.message}`,
    };
  }

  const allowedRelevance = ['enforcement', 'not_enforcement', 'uncertain'];
  if (!allowedRelevance.includes(analysis.relevance)) analysis.relevance = 'uncertain';
  analysis.confidence = Math.max(0, Math.min(1, Number(analysis.confidence || 0)));
  delete analysis.verification_status;
  delete analysis.review_status;
  delete analysis.published;

  return {
    json: {
      source_code: base.source_code,
      jurisdiction: base.jurisdiction,
      regulator: base.regulator,
      source_page: base.source_page,
      url: base.url,
      title: base.title,
      publication_date: base.publication_date,
      discovered_at: base.discovered_at,
      language: base.language,
      official_text: base.official_text,
      document_type: 'official_announcement',
      verification_status: 'unverified',
      pipeline_version: 'regintel-n8n-v1',
      workflow_execution_id: $execution.id,
      anysearch_evidence: base.anysearch_evidence,
      ai_analysis: analysis,
    },
  };
});
